def cls_of(k, mean, n=16):
    if mean >= .60 and k >= math.ceil(.75 * n):
        return "SUPER"
    if k <= math.floor(.5 * n) and mean <= .50:
        return "NOT-SUPER"
    return "INTERMEDIATE"


def paired(x, y):
    d = np.asarray(x, float) - np.asarray(y, float)
    mu, sd = float(d.mean()), float(d.std(ddof=1))
    h = T975[len(d) - 1] * sd / math.sqrt(len(d))
    return dict(mean=round(mu, 4), sd=round(sd, 4), ci95=[round(mu - h, 4), round(mu + h, 4)],
                lo=mu - h, hi=mu + h, n_lower=int((d < 0).sum()), n_higher=int((d > 0).sum()),
                n_up=int((d >= .2).sum()), n_dn=int((d <= -.2).sum()), n=len(d))


