    meanL, meanR = round(float(L.mean()), 3), round(float(R.mean()), 3)
    return dict(n=n, kL=kL, meanL=meanL, clsL=cls_of(kL, meanL, n), dutyL=[float(v) for v in L],
                kR=kR, meanR=meanR, clsR=cls_of(kR, meanR, n), dutyR=[float(v) for v in R],
                k14L=int((d14L >= .5).sum()), mean14L=round(float(d14L.mean()), 3),
                duty14L=[float(v) for v in d14L], sigL=bool(float(d14L.mean()) >= SIG),
                k14R=int((d14R >= .5).sum()), mean14R=round(float(d14R.mean()), 3),
                duty14R=[float(v) for v in d14R], sigR=bool(float(d14R.mean()) >= SIG))


